const SELECTABLE = ['id', 'email', 'createdAt'] as const;
type Selectable = (typeof SELECTABLE)[number];
type Projected<K extends Selectable> = Pick<User, K>;

function project<K extends Selectable>(row: User, fields: readonly K[]): Projected<K> {
  const unknown = fields.filter((f) => !(SELECTABLE as readonly string[]).includes(f));
  if (unknown.length) throw new HttpError(400, `unknown fields: ${unknown.join(',')}`);
  return Object.fromEntries(fields.map((f) => [f, row[f]])) as Projected<K>;
}

